css:
body { padding: 1.5rem; }

@keyframes wink {
  0%, 100% { transform: scale(1) rotate(0); }
  50% { transform: scale(1.15) rotate(-4deg); }
}
.wink {
  animation: wink 0.4s ease;
}

js:
// Bootstrap's CSS and JS are already loaded in this preview.
