const winkBtn = document.getElementById('winkBtn');
winkBtn.addEventListener('click', () => {
  winkBtn.textContent = '😉 Nice click!';
  winkBtn.classList.add('wink');
  setTimeout(() => {
    winkBtn.textContent = 'Click me';
    winkBtn.classList.remove('wink');
  }, 900);
});
